/**
 * Link version 1, frozen: the scenario library channel (the scenarios and the built-in templates).
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

import type { ScenarioDocumentV1 } from './shapesScenarios';

export type ScenarioLibraryChannelsV1 = {
    'get-scenarios': {
        args: [];
        result:
            | { success: false; error: string; issues?: undefined }
            | {
                  success: true;
                  scenarios: { [key: string]: ScenarioDocumentV1 };
                  templates: (
                      | {
                            id: string;
                            scenario: {
                                name: string;
                                version: number;
                                description: string;
                                start: string;
                                phases: {
                                    buildup: {
                                        settings: {
                                            exposure: number;
                                            exposureTarget: number;
                                            useFinalWindowExposure: boolean;
                                            autoSubmit: boolean;
                                            autoBoost: boolean;
                                        };
                                        rules: (
                                            | {
                                                  id: string;
                                                  label: string;
                                                  repeat: string;
                                                  if: (
                                                      | {
                                                            type: string;
                                                            from: string;
                                                            to: string;
                                                            max?: undefined;
                                                            op?: undefined;
                                                            value?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            max: string;
                                                            from?: undefined;
                                                            to?: undefined;
                                                            op?: undefined;
                                                            value?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            op: string;
                                                            value: number;
                                                            from?: undefined;
                                                            to?: undefined;
                                                            max?: undefined;
                                                        }
                                                  )[];
                                                  do: { type: string; photo: string }[];
                                              }
                                            | {
                                                  id: string;
                                                  label: string;
                                                  if: (
                                                      | {
                                                            type: string;
                                                            min: string;
                                                            select?: undefined;
                                                            field?: undefined;
                                                            window?: undefined;
                                                            op?: undefined;
                                                            value?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            select: { by: string; window: string };
                                                            field: string;
                                                            window: string;
                                                            op: string;
                                                            value: number;
                                                            min?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            select: { by: string; window: string };
                                                            field: string;
                                                            op: string;
                                                            value: number;
                                                            min?: undefined;
                                                            window?: undefined;
                                                        }
                                                  )[];
                                                  do: (
                                                      | {
                                                            type: string;
                                                            entry: { by: string; window: string };
                                                            with: string;
                                                            rememberRemoved: string;
                                                            rememberAdded: string;
                                                            phase?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            phase: string;
                                                            entry?: undefined;
                                                            with?: undefined;
                                                            rememberRemoved?: undefined;
                                                            rememberAdded?: undefined;
                                                        }
                                                  )[];
                                                  repeat?: undefined;
                                              }
                                            | {
                                                  id: string;
                                                  label: string;
                                                  repeat: string;
                                                  if: (
                                                      | {
                                                            type: string;
                                                            from: string;
                                                            to: string;
                                                            max?: undefined;
                                                            in?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            max: string;
                                                            from?: undefined;
                                                            to?: undefined;
                                                            in?: undefined;
                                                        }
                                                      | {
                                                            type: string;
                                                            in: string[];
                                                            from?: undefined;
                                                            to?: undefined;
                                                            max?: undefined;
                                                        }
                                                  )[];
                                                  do: (
                                                      | { type: string; entry: { by: string }; phase?: undefined }
                                                      | { type: string; phase: string; entry?: undefined }
                                                  )[];
                                              }
                                        )[];
                                    };
                                    holding: {
                                        settings: {
                                            exposure: number;
                                            exposureTarget: number;
                                            useFinalWindowExposure: boolean;
                                            autoSubmit: boolean;
                                            autoBoost: boolean;
                                        };
                                        rules: {
                                            id: string;
                                            label: string;
                                            repeat: string;
                                            if: (
                                                | { type: string; from: string; to: string; max?: undefined }
                                                | { type: string; max: string; from?: undefined; to?: undefined }
                                            )[];
                                            do: (
                                                | {
                                                      type: string;
                                                      entry: { by: string; slot: string };
                                                      with: { memory: string };
                                                      phase?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      entry: { by: string; slot: string };
                                                      with?: undefined;
                                                      phase?: undefined;
                                                  }
                                                | { type: string; phase: string; entry?: undefined; with?: undefined }
                                            )[];
                                        }[];
                                    };
                                    pulse: {
                                        settings: { autoSubmit: boolean; autoBoost: boolean };
                                        rules: {
                                            id: string;
                                            label: string;
                                            if: {
                                                type: string;
                                                select: { by: string; slot: string };
                                                field: string;
                                                op: string;
                                                value: number;
                                            }[];
                                            do: (
                                                | {
                                                      type: string;
                                                      entry: { by: string; slot: string };
                                                      with: string;
                                                      rememberAdded: string;
                                                      phase?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      phase: string;
                                                      entry?: undefined;
                                                      with?: undefined;
                                                      rememberAdded?: undefined;
                                                  }
                                            )[];
                                        }[];
                                    };
                                    pulseWait: {
                                        settings: { autoSubmit: boolean; autoBoost: boolean };
                                        rules: {
                                            id: string;
                                            label: string;
                                            if: { type: string; min: string }[];
                                            do: (
                                                | {
                                                      type: string;
                                                      entry: { by: string; slot: string };
                                                      with: { memory: string };
                                                      phase?: undefined;
                                                  }
                                                | { type: string; phase: string; entry?: undefined; with?: undefined }
                                            )[];
                                        }[];
                                    };
                                    done: {};
                                    main?: undefined;
                                };
                                limits?: undefined;
                            };
                        }
                      | {
                            id: string;
                            scenario: {
                                name: string;
                                version: number;
                                description: string;
                                start: string;
                                phases: {
                                    main: {
                                        settings: { autoBoost: boolean; useTurbo?: undefined };
                                        rules: {
                                            id: string;
                                            repeat: string;
                                            if: (
                                                | {
                                                      type: string;
                                                      from: string;
                                                      to: string;
                                                      min?: undefined;
                                                      max?: undefined;
                                                      in?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      min: string;
                                                      max: string;
                                                      from?: undefined;
                                                      to?: undefined;
                                                      in?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      in: string[];
                                                      from?: undefined;
                                                      to?: undefined;
                                                      min?: undefined;
                                                      max?: undefined;
                                                  }
                                            )[];
                                            do: { type: string; entry: { by: string } }[];
                                        }[];
                                    };
                                    buildup?: undefined;
                                    holding?: undefined;
                                    pulse?: undefined;
                                    pulseWait?: undefined;
                                    done?: undefined;
                                };
                                limits?: undefined;
                            };
                        }
                      | {
                            id: string;
                            scenario: {
                                name: string;
                                version: number;
                                description: string;
                                start: string;
                                limits: { swaps: number };
                                phases: {
                                    main: {
                                        rules: {
                                            id: string;
                                            repeat: string;
                                            if: (
                                                | {
                                                      type: string;
                                                      min: string;
                                                      from?: undefined;
                                                      to?: undefined;
                                                      currency?: undefined;
                                                      op?: undefined;
                                                      value?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      from: string;
                                                      to: string;
                                                      min?: undefined;
                                                      currency?: undefined;
                                                      op?: undefined;
                                                      value?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      currency: string;
                                                      op: string;
                                                      value: number;
                                                      min?: undefined;
                                                      from?: undefined;
                                                      to?: undefined;
                                                  }
                                            )[];
                                            do: {
                                                type: string;
                                                entry: { by: string; skipProtected: boolean };
                                                with: string;
                                            }[];
                                        }[];
                                        settings?: undefined;
                                    };
                                    buildup?: undefined;
                                    holding?: undefined;
                                    pulse?: undefined;
                                    pulseWait?: undefined;
                                    done?: undefined;
                                };
                            };
                        }
                      | {
                            id: string;
                            scenario: {
                                name: string;
                                version: number;
                                description: string;
                                start: string;
                                phases: {
                                    main: {
                                        settings: { useTurbo: boolean; autoBoost?: undefined };
                                        rules: {
                                            id: string;
                                            repeat: string;
                                            if: (
                                                | {
                                                      type: string;
                                                      in: string[];
                                                      select?: undefined;
                                                      field?: undefined;
                                                      op?: undefined;
                                                      value?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      select: { by: string };
                                                      field: string;
                                                      op: string;
                                                      value: number;
                                                      in?: undefined;
                                                  }
                                                | {
                                                      type: string;
                                                      select: { by: string };
                                                      field: string;
                                                      op: string;
                                                      value: boolean;
                                                      in?: undefined;
                                                  }
                                            )[];
                                            do: { type: string; entry: { by: string } }[];
                                        }[];
                                    };
                                    buildup?: undefined;
                                    holding?: undefined;
                                    pulse?: undefined;
                                    pulseWait?: undefined;
                                    done?: undefined;
                                };
                                limits?: undefined;
                            };
                        }
                  )[];
              };
    };
};
